-- public.delete_market
-- Generated by scripts/schema-snapshot.mjs from project heuhqqoxyggawuckxocp. Do not edit by hand.

-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.delete_market(p_market uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_kind text;
  v_members int;
  v_challenges int;
begin
  if not public.is_admin() then raise exception 'Only admins can delete a market'; end if;

  select kind into v_kind from public.communities where id = p_market;
  if v_kind is null then raise exception 'No such market'; end if;
  if v_kind <> 'chapter' then raise exception 'Only a market can be deleted'; end if;

  -- Real creators only: the market's own managers were added when it was
  -- created, and the sandbox account is in every market by design.
  select count(*) into v_members
    from public.community_members cm
    join public.profiles p on p.id = cm.profile_id
   where cm.community_id = p_market
     and cm.status = 'active'
     and cm.role = 'creator'
     and coalesce(p.is_test, false) = false;

  select count(*) into v_challenges from public.challenges where community_id = p_market;

  if v_members > 0 then
    raise exception 'That market has % creator(s) in it. Retire it instead.', v_members;
  end if;
  if v_challenges > 0 then
    raise exception 'That market has % challenge(s). Retire it instead.', v_challenges;
  end if;

  delete from public.market_join_requests where community_id = p_market;
  delete from public.channels where community_id = p_market;
  delete from public.community_members where community_id = p_market;
  delete from public.communities where id = p_market;
end;
$function$;
